package com.fit.badminton.payment; import com.fit.badminton.auth.*; import com.fit.badminton.settlement.SettlementTransfer; import java.util.Map; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/transfers") public class AdminPaymentController {private final PaymentService payments;private final UserAccountService users;public AdminPaymentController(PaymentService p,UserAccountService u){payments=p;users=u;} @PostMapping("/{id}/mark-unpaid") public Map<String,Object> reset(@PathVariable long id,Authentication a){UserRole role=users.getByUsername(a.getName()).getRole();SettlementTransfer t=payments.markUnpaidAdmin(id,role);return Map.of("id",t.getId(),"status",t.getStatus().name());}}
